int
count_open_fds()
{
        int i;
        int count = 0;

        for (i = 0; i < FD_SETSIZE; i++) {
                int fd = dup(i);

                if (fd >= 0) {
                        count++;
                        if (close(fd) < 0) {
                                perror("count_open_fds");
                                fuzz_trap();
                        }
                }
        }

        return count;
}

